{"pluginId":"default","name":"轻快完成（停用 due）","parentId":"27fc6fead3ceca85ca54a19b72e5fe45fead4738e28b802eae84cd6e122ea6b2","service":"workflow","contractVersion":"workflow/1","source":"{"files":[{"content":"import type { Workflow } from \"./contract.js\";\nexport const workflow: Workflow = {\n  definition: {\n    id: \"default\",\n    name: \"轻快完成\",\n    version: \"1.0.0\",\n    initialState: \"open\",\n    states: {\n      open: { label: \"未完成\", category: \"open\" },\n      done: { label: \"已完成\", category: \"done\" },\n    },\n    actions: [\n      { id: \"complete\", label: \"完成\", from: [\"open\"] },\n      { id: \"reopen\", label: \"重新打开\", from: [\"done\"] },\n    ],\n    fields: [],\n  },\n  decide(task, action) {\n    if (\n      !this.definition.actions.some(\n        (a) => a.id === action && a.from.includes(task.state),\n      )\n    )\n      return { kind: \"reject\", message: \"当前状态不能执行此操作\" };\n    return {\n      kind: \"commit\",\n      state: action === \"complete\" ? \"done\" : \"open\",\n      fields: task.fields,\n    };\n  },\n};\n\nexport default {\n  describe: () => workflow.definition,\n  decide: (data: {\n    task: Parameters<typeof workflow.decide>[0];\n    action: string;\n    input: Record<string, string>;\n  }) => workflow.decide(data.task, data.action, data.input),\n};","path":"business/entry.ts"},{"content":"export default {\n  title: \"轻快完成\",\n  fields: []\n};","path":"business/view.ts"},{"content":"{}","path":"business/config.json"},{"path":"business/compatibility.json","content":"{\"preserveUnknownFields\":true}"}]}","code":"export const workflow = {
    definition: {
        id: "default",
        name: "轻快完成",
        version: "1.0.0",
        initialState: "open",
        states: {
            open: { label: "未完成", category: "open" },
            done: { label: "已完成", category: "done" },
        },
        actions: [
            { id: "complete", label: "完成", from: ["open"] },
            { id: "reopen", label: "重新打开", from: ["done"] },
        ],
        fields: [],
    },
    decide(task, action) {
        if (!this.definition.actions.some((a) => a.id === action && a.from.includes(task.state)))
            return { kind: "reject", message: "当前状态不能执行此操作" };
        return {
            kind: "commit",
            state: action === "complete" ? "done" : "open",
            fields: task.fields,
        };
    },
};
export default {
    describe: () => workflow.definition,
    decide: (data) => workflow.decide(data.task, data.action, data.input),
};
